SELECT * FROM `gateway`
WHERE `delete_at` IS NULL AND `gateway_type` = 'RS485'
ORDER BY `create_at` DESC;

SELECT * FROM `gateway`
WHERE `delete_at` IS NULL AND `gateway_type` = 'RS485' AND `id` = #{gateway_id}
